<?php
declare(strict_types=1);
namespace Tests\Feature\Jobs\Chat;
use App\Enums\UserStatus; use App\Jobs\Chat\ChatDatabaseNotificationJob; use App\Jobs\Chat\ChatMailNotificationJob; use App\Models\NotificationDeliveryAttempt; use App\Services\Notifications\NotificationAttemptTracker; use App\Models\ChatMember; use App\Models\ChatMessage; use App\Models\ChatRoom; use App\Models\Enrollment; use App\Models\User; use App\Notifications\ChatMessageReceivedNotification; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Notifications\DatabaseNotification; use Illuminate\Support\Facades\Mail; use Tests\TestCase;
final class ChatNotificationJobsFeatureTest extends TestCase { use RefreshDatabase; private function data():array{$s=User::factory()->student()->inProgress()->create();$r=User::factory()->coach()->inProgress()->create();$room=ChatRoom::factory()->for(Enrollment::factory()->for($s))->create();ChatMember::factory()->create(['chat_room_id'=>$room->id,'user_id'=>$s->id]);ChatMember::factory()->create(['chat_room_id'=>$room->id,'user_id'=>$r->id]);$m=ChatMessage::factory()->create(['chat_room_id'=>$room->id,'sender_user_id'=>$s->id,'body'=>'本文確認']);return[$m,$r];}
 public function test_database_job_persists_once_with_payload():void{[$m,$r]=$this->data();$j=new ChatDatabaseNotificationJob((string)$m->id,(string)$r->id);$j->handle();$j->handle();$rows=DatabaseNotification::where('notifiable_id',$r->id)->where('type',ChatMessageReceivedNotification::class)->get();$this->assertCount(1,$rows);$this->assertSame('本文確認',$rows[0]->data['body_preview']);$this->assertSame('chat.show',$rows[0]->data['redirect_route']);$this->assertSame(ChatDatabaseNotificationJob::notificationId((string)$m->id,(string)$r->id),(string)$rows[0]->id);}
 public function test_inactive_recipient_is_skipped():void{[$m,$r]=$this->data();$r->update(['status'=>UserStatus::Withdrawn->value]);(new ChatDatabaseNotificationJob((string)$m->id,(string)$r->id))->handle();$this->assertDatabaseMissing('notifications',['notifiable_id'=>$r->id]);}
 public function test_mail_job_does_not_create_database_notification():void{Mail::fake();[$m,$r]=$this->data();(new ChatMailNotificationJob((string)$m->id,(string)$r->id))->handle();Mail::assertNothingQueued();$this->assertDatabaseMissing('notifications',['notifiable_id'=>$r->id]);} public function test_attempt_counter_is_persisted_and_channels_are_independent():void{[$m,$r]=$this->data();$t=app(NotificationAttemptTracker::class);$this->assertSame(1,$t->increment('chat:'.$m->id,(string)$r->id,'database'));$this->assertSame(2,$t->increment('chat:'.$m->id,(string)$r->id,'database'));$this->assertSame(1,$t->increment('chat:'.$m->id,(string)$r->id,'mail'));$this->assertSame(2,NotificationDeliveryAttempt::where('event_key','chat:'.$m->id)->where('recipient_id',$r->id)->count());} public function test_attempt_counter_stays_at_three_after_limit():void{[$m,$r]=$this->data();$t=app(NotificationAttemptTracker::class);$this->assertSame(1,$t->increment('chat:'.$m->id,(string)$r->id,'mail'));$this->assertSame(2,$t->increment('chat:'.$m->id,(string)$r->id,'mail'));$this->assertSame(3,$t->increment('chat:'.$m->id,(string)$r->id,'mail'));$this->assertSame(3,$t->increment('chat:'.$m->id,(string)$r->id,'mail'));$this->assertSame(3,(int)NotificationDeliveryAttempt::where('event_key','chat:'.$m->id)->where('channel','mail')->value('attempts'));}
}


